/**
 * Font Asset Ambient Module Declarations for TypeScript
 *
 * Allows ES imports and require resolutions for font binaries (*.otf, *.ttf, *.woff, *.woff2)
 * in React Native / Expo SDK 57 projects.
 */

declare module "*.otf" {
  const value: any;
  export default value;
}

declare module "*.ttf" {
  const value: any;
  export default value;
}

declare module "*.woff" {
  const value: any;
  export default value;
}

declare module "*.woff2" {
  const value: any;
  export default value;
}
